create table if not exists organizations (id text primary key, name text not null, slug text not null unique);
    create table if not exists accounts (id text primary key, organization_id text not null references organizations(id), name text not null, email text not null unique, password_hash text not null, role text not null check(role in ('owner','admin','supervisor','agent','customer')), status text not null check(status in ('pending_email','active','suspended')), verified_at text, created_at text not null, updated_at text not null, privacy_notice_version text not null, privacy_ack_at text, failed_attempts integer not null default 0, locked_until text);
    create table if not exists sessions (id text primary key, account_id text not null references accounts(id) on delete cascade, expires_at text not null, revoked_at text, created_at text not null);
    create index if not exists sessions_account on sessions(account_id,expires_at);
    create table if not exists auth_tokens (id text primary key, account_id text not null references accounts(id) on delete cascade, purpose text not null check(purpose in ('verify_email','reset_password')), token_hash text not null unique, expires_at text not null, consumed_at text, created_at text not null);
    create table if not exists privacy_requests (id text primary key, account_id text not null references accounts(id), request_kind text not null, status text not null default 'pending', created_at text not null);
    create table if not exists agents (id text primary key, organization_id text not null references organizations(id), name text not null, email text not null, role text not null);
    create table if not exists companies (id text primary key, organization_id text not null references organizations(id), name text not null, plan text not null, mrr_cents integer not null default 0, health_score integer not null default 80, account_status text not null default 'active');
    create table if not exists customers (id text primary key, organization_id text not null references organizations(id), company_id text references companies(id), name text not null, email text not null, plan text not null default 'Business', satisfaction real not null default 4.5);
    create table if not exists sla_policies (id text primary key, organization_id text not null references organizations(id), name text not null, first_response_minutes integer not null, resolution_minutes integer not null);
    create table if not exists tickets (id text primary key, organization_id text not null references organizations(id), number integer not null, subject text not null, description text not null, status text not null check(status in ('open','in_progress','waiting_customer','resolved','closed')), priority text not null check(priority in ('low','medium','high','urgent')), channel text not null check(channel in ('portal','web')), customer_id text not null references customers(id), company_id text references companies(id), assignee_id text references agents(id), sla_policy_id text references sla_policies(id), sentiment text not null default 'neutral', created_at text not null, updated_at text not null, first_response_at text, resolved_at text, unique(organization_id,number));
    create index if not exists tickets_queue on tickets(organization_id,status,priority,updated_at desc);
    create index if not exists tickets_customer on tickets(organization_id,customer_id,created_at desc);
    create table if not exists messages (id text primary key, organization_id text not null references organizations(id), ticket_id text not null references tickets(id) on delete cascade, author_id text, author_name text not null, visibility text not null check(visibility in ('public','internal')), body text not null, created_at text not null);
    create index if not exists messages_timeline on messages(organization_id,ticket_id,created_at);
    create table if not exists events (id text primary key, organization_id text not null references organizations(id), ticket_id text not null references tickets(id) on delete cascade, kind text not null, actor_name text not null, old_value text, new_value text, created_at text not null);
    create table if not exists tags (id text primary key, organization_id text not null references organizations(id), name text not null, unique(organization_id,name));
    create table if not exists ticket_tags (ticket_id text not null references tickets(id) on delete cascade, tag_id text not null references tags(id), primary key(ticket_id,tag_id));
    create table if not exists articles (id text primary key, organization_id text not null references organizations(id), category text not null, title text not null, slug text not null, body text not null, status text not null check(status in ('draft','published')), author text not null, views integer not null default 0, helpful_votes integer not null default 0, created_at text not null, updated_at text not null, unique(organization_id,slug));
    create table if not exists automations (id text primary key, organization_id text not null references organizations(id), name text not null, trigger_kind text not null, condition_field text not null, condition_value text not null, action_kind text not null, action_value text not null, enabled integer not null default 0, created_at text not null);
    create table if not exists automation_runs (id text primary key, organization_id text not null references organizations(id), automation_id text not null references automations(id), ticket_id text not null references tickets(id), details text not null, created_at text not null);
    create table if not exists notifications (id text primary key, organization_id text not null references organizations(id), recipient_id text not null, kind text not null, body text not null, ticket_id text references tickets(id), read_at text, created_at text not null);
    create index if not exists notifications_unread on notifications(organization_id,recipient_id,read_at,created_at desc);
    create table if not exists macros (id text primary key, organization_id text not null references organizations(id), command text not null, title text not null, body text not null, status text, priority text, tag text);
    create table if not exists feedback (id text primary key, organization_id text not null references organizations(id), ticket_id text not null unique references tickets(id), customer_id text not null references customers(id), rating integer not null check(rating between 1 and 5), comment text, created_at text not null);
    create table if not exists attachments (id text primary key, organization_id text not null references organizations(id), ticket_id text not null references tickets(id) on delete cascade, author_id text not null, visibility text not null check(visibility in ('public','internal')), file_name text not null, mime_type text not null, size_bytes integer not null, storage_path text not null, created_at text not null);
    create table if not exists audit_logs (id text primary key, organization_id text not null references organizations(id), actor_id text not null, entity_type text not null, entity_id text not null, action text not null, old_value text, new_value text, created_at text not null);
    create table if not exists saved_views (id text primary key, organization_id text not null references organizations(id), actor_id text not null, name text not null, filters text not null, created_at text not null);
